                     exists|i: int|
                         #[trigger] self.bitmap@.set_bits.contains(i)
                         && addr == frame_addr_of(i),
                 |addr: int| {
                     let i = addr / spec_page_size();
                     self.refcount@[i] as int
                 },
             ),
         }
     }
